import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

hinge_loss_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void hinge_loss_forward_kernel(const float* predictions,
                                          const float* targets,
                                          float* partial_sum,
                                          int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = 1.0f - (predictions[idx] * targets[idx]);
        if (val < 0.0f) {
            val = 0.0f;
        }
        atomicAdd(partial_sum, val);
    }
}

torch::Tensor hinge_loss_cuda(torch::Tensor predictions, torch::Tensor targets) {
    auto size = predictions.numel();
    auto partial_sum = torch::zeros({1}, predictions.options());

    const int block_size = 256;
    const int grid_size = (size + block_size - 1) / block_size;

    hinge_loss_forward_kernel<<<grid_size, block_size>>>(
        predictions.data_ptr<float>(),
        targets.data_ptr<float>(),
        partial_sum.data_ptr<float>(),
        size);

    // Compute mean
    auto loss = partial_sum / (float)size;
    return loss;
}
"""

hinge_loss_cpp_source = r"""
torch::Tensor hinge_loss_cuda(torch::Tensor predictions, torch::Tensor targets);
"""

hinge_loss = load_inline(
    name="hinge_loss",
    cpp_sources=hinge_loss_cpp_source,
    cuda_sources=hinge_loss_source,
    functions=["hinge_loss_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized model with custom CUDA hinge loss.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.hinge_loss = hinge_loss

    def forward(self, predictions, targets):
        return self.hinge_loss.hinge_loss_cuda(predictions, targets)
